"""Profiling: BLITZLLVM_PROFILE_FPS=1 and the command ProfileFPS only report in a program that was compiled with --profile (or -d).

  profile.py BLITZCC PROGRAM.bb WORKDIR on|debug|off [env|command|silenced]

env (the default): the environment variable asks for the report. command: the program asks with ProfileFPS 1 and the
environment is clean. silenced: the environment asks, but the program turns the timers off with ProfileEnable 0.
Without --profile the commands are no-ops, so the program still has to compile and run.
"""
import os
import subprocess
import sys
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "../../tools"))
import procutil  # noqa: E402


def main():
    blitzcc, source, work, mode = sys.argv[1], sys.argv[2], os.path.abspath(sys.argv[3]), sys.argv[4]
    variant = sys.argv[5] if len(sys.argv) > 5 else "env"
    os.makedirs(work, exist_ok=True)
    exe = os.path.join(work, "profile")
    flags = {"on": ["--profile"], "debug": ["-d"], "off": []}[mode]
    procutil.run([blitzcc] + flags + [source, "-o", exe], check=True, stdout=subprocess.DEVNULL)
    env = {k: v for k, v in os.environ.items() if not k.startswith("BLITZLLVM_PROFILE_")}
    if variant != "command":
        env["BLITZLLVM_PROFILE_FPS"] = "1"
    result = procutil.run([exe], env=env, capture_output=True, text=True, timeout=60)
    reported = "fps:" in result.stderr
    expected = (mode != "off") and variant != "silenced"
    if result.returncode != 0:
        print("profile: the program failed with %d.\n%s" % (result.returncode, result.stderr))
        return 1
    if reported != expected:
        print("profile (%s): the report %s, but the program was compiled with profiling %s.\n%s" % (variant, "came" if reported else "did not come", mode, result.stderr))
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
